  @Patch('orders/:id')
  async updateOrder(@Req() request: V2Request, @Param('id') id: string, @Body() body: JsonObject, @Res({ passthrough: true }) reply: FastifyReply): Promise<unknown> { const principal = principalOf(request); const expected = etag(request); const commandBoundary = `updateOrderV2:${header(request, 'idempotency-key')!}`; return this.mutate(request, reply, 'updateOrderV2', 200, async (client) => { requirePermission(principal, 'order.update', 'ORDER'); const row = (await client.query<OrderRow>('SELECT id,organization_id,version,created_at,updated_at,customer_id,order_no,owner_user_id,business_group_id,currency,status,stage,total_amount::text,metadata FROM orders.order_header WHERE organization_id=$1 AND id=$2 FOR UPDATE', [principal.organizationId, id])).rows[0]; if (row === undefined || !visible(principal, row)) throw this.problem(404, 'RESOURCE_NOT_FOUND', 'Resource not found', request); if (Number(row.version) !== expected) throw versionProblem(request, Number(row.version), `/api/v2/orders/${id}`); if (row.status !== 'DRAFT' || !['INITIAL_CONTACT', 'QUOTING', 'QUOTE_FOLLOW_UP'].includes(row.stage)) throw stateProblem(request, id, row.status, 'ORDER'); if (Object.hasOwn(body, 'lines')) await this.replaceLines(client, principal, row, arrayRequired(body, 'lines'), request, commandBoundary); await client.query(`UPDATE orders.order_header SET metadata=CASE WHEN $3::boolean THEN $4::jsonb ELSE metadata END,total_amount=COALESCE((SELECT COALESCE(sum(line_amount_v2),0) FROM orders.order_item WHERE organization_id=$1 AND order_id=$2),total_amount),version=version+1,updated_at=clock_timestamp() WHERE organization_id=$1 AND id=$2 AND version=$5`, [principal.organizationId, id, Object.hasOwn(body, 'metadata'), JSON.stringify(objectOptional(body, 'metadata') ?? {}), expected]); await appendAudit(client, principal, 'order.updated', 'ORDER', id, requestId(request)); await appendOutbox(client, principal.organizationId, id, 'order.updated', requestId(request)); const updated = (await client.query<OrderRow>('SELECT id,organization_id,version,created_at,updated_at,customer_id,order_no,owner_user_id,business_group_id,currency,status,stage,total_amount::text,metadata FROM orders.order_header WHERE organization_id=$1 AND id=$2', [principal.organizationId, id])).rows[0]!; const href = `/api/v2/orders/${id}`; return { body: await this.orderApi(updated, client, principal), resource: { type: 'ORDER', id, version: Number(updated.version), href }, headers: { 'cache-control': 'no-store', etag: formatEtag(Number(updated.version)) } }; }); }

  @Post('orders/:id/transitions')
  async transitionOrder(@Req() request: V2Request, @Param('id') id: string, @Body() body: JsonObject, @Res({ passthrough: true }) reply: FastifyReply): Promise<unknown> { const principal = principalOf(request); const expected = etag(request); return this.mutate(request, reply, 'transitionOrderV2', 200, async (client) => { requirePermission(principal, 'order.transition', 'ORDER'); const row = (await client.query<OrderRow>('SELECT id,organization_id,version,created_at,updated_at,customer_id,order_no,owner_user_id,business_group_id,currency,status,stage,total_amount::text,metadata FROM orders.order_header WHERE organization_id=$1 AND id=$2 FOR UPDATE', [principal.organizationId, id])).rows[0]; if (row === undefined || !visible(principal, row)) throw this.problem(404, 'RESOURCE_NOT_FOUND', 'Resource not found', request); if (Number(row.version) !== expected) throw versionProblem(request, Number(row.version), `/api/v2/orders/${id}`); if (row.status === 'CANCELLED' || row.status === 'FULFILLED' || row.stage === 'CLOSED') throw this.problem(409, 'INVALID_TRANSITION', 'Order is terminal', request); const action = stringRequired(body, 'action'); if (action === 'CANCEL') { await client.query(`UPDATE orders.order_header SET status='CANCELLED',version=version+1,updated_at=clock_timestamp() WHERE organization_id=$1 AND id=$2 AND version=$3`, [principal.organizationId, id, expected]); } else if (action === 'ADVANCE') { const next = stringRequired(body, 'toStage') as Stage; if (!isAdjacent(row.stage, next)) throw this.problem(409, 'INVALID_TRANSITION', 'Order transition is not adjacent', request); await client.query(`UPDATE orders.order_header SET stage=$4,status=$5,version=version+1,updated_at=clock_timestamp() WHERE organization_id=$1 AND id=$2 AND version=$3`, [principal.organizationId, id, next, statusForStage(next)]); await client.query(`INSERT INTO orders.stage_history (id,organization_id,order_id,from_stage,to_stage,actor_user_id,reason) VALUES ($1,$2,$3,$4,$5,$6,$7)`, [randomUUID(), principal.organizationId, id, row.stage, next, principal.userId, stringOptional(body, 'reason') ?? null]); } else throw this.problem(400, 'VALIDATION_FAILED', 'Unknown transition action', request); await appendAudit(client, principal, action === 'CANCEL' ? 'order.cancelled' : 'order.transitioned', 'ORDER', id, requestId(request)); await appendOutbox(client, principal.organizationId, id, action === 'CANCEL' ? 'order.cancelled' : 'order.transitioned', requestId(request)); const updated = (await client.query<OrderRow>('SELECT id,organization_id,version,created_at,updated_at,customer_id,order_no,owner_user_id,business_group_id,currency,status,stage,total_amount::text,metadata FROM orders.order_header WHERE organization_id=$1 AND id=$2', [principal.organizationId, id])).rows[0]!; const href = `/api/v2/orders/${id}`; return { body: await this.orderApi(updated, client, principal), resource: { type: 'ORDER', id, version: Number(updated.version), href }, headers: { 'cache-control': 'no-store', etag: formatEtag(Number(updated.version)) } }; }); }

